// Generated by @canonical/summon-component:react v0.43.0

import { collectLenses, setPrefetchEnvironment } from "@canonical/prism-core";
import { screen, within } from "@testing-library/react";
import { afterAll, afterEach, beforeAll, describe, expect, it } from "vitest";
import createMetroExecute from "../../../../../../../testing/createMetroExecute.js";
import {
  LINE_COUNT,
  ROLLING_STOCK_COUNT,
  STATION_COUNT,
} from "../../../../../../../testing/fixtures.js";
import renderLensPage from "../../../../../../../testing/renderLensPage.js";
import startMetroGraph from "../../../../../../../testing/startMetroGraph.js";
import type { MetroGraph } from "../../../../../../../testing/types.js";
import { appRoutes } from "../../../../../../routes.js";

let graph: MetroGraph;

beforeAll(async () => {
  graph = await startMetroGraph();
});

afterEach(() => {
  setPrefetchEnvironment(undefined);
});

afterAll(() => graph.close());

/** How many classes the graph's ontologies declare between them. */
const countGraphClasses = async (): Promise<number> => {
  const result = await createMetroExecute()(
    "{ ontologies { classes { uri } } }",
    {},
  );
  const ontologies = (
    result.data as {
      readonly ontologies: readonly { readonly classes: readonly unknown[] }[];
    }
  ).ontologies;
  return ontologies.reduce((total, { classes }) => total + classes.length, 0);
};

/** The landing's doors, once the counts have answered. */
const findDoors = async (): Promise<HTMLElement[]> => {
  await screen.findByRole("heading", { level: 2, name: "Stations" });
  return [
    ...document.querySelectorAll<HTMLElement>(
      ".ds.cards.lens-cards > .lens-card",
    ),
  ];
};

describe("LensCards", () => {
  it("opens one door per lens, in rail order, each to its index", async () => {
    renderLensPage("/", graph.url);
    const doors = await findDoors();
    const lenses = collectLenses(appRoutes);
    expect(
      doors.map((door) => within(door).getByRole("heading").textContent),
    ).toEqual(lenses.map(({ label }) => label));
    expect(
      doors.map((door) => within(door).getByRole("link").getAttribute("href")),
    ).toEqual(["/stations", "/lines", "/definitions", "/fleet"]);
  });

  it("states each lens's count as the graph gives it", async () => {
    renderLensPage("/", graph.url);
    const doors = await findDoors();
    const classes = await countGraphClasses();
    expect(
      doors.map((door) => door.querySelector("data")?.getAttribute("value")),
    ).toEqual([
      String(STATION_COUNT),
      String(LINE_COUNT),
      String(classes),
      String(ROLLING_STOCK_COUNT),
    ]);
    expect(doors.at(0)?.querySelector("data")?.textContent).toBe(
      `${STATION_COUNT} stations`,
    );
    expect(doors.at(2)?.querySelector("data")?.textContent).toBe(
      `${classes} classes`,
    );
    expect(doors.at(3)?.querySelector("data")?.textContent).toBe(
      `${ROLLING_STOCK_COUNT} rolling stocks`,
    );
  });

  it("lays the doors out in the published Cards group", async () => {
    renderLensPage("/", graph.url);
    await findDoors();
    const group = document.querySelector(".lens-cards");
    expect(group?.className).toBe("ds cards subgrid ds lens-cards");
    expect(group?.getAttribute("style")).toContain("--card-span: 2");
  });
});
